// Islandora AS2 event: object.url is a list of links to the file/derivatives.
const event = msg.payload;
const links = (event.object && event.object.url) || [];
const file = links.find(l => (l.mediaType || '').includes('pdf')) || links[0];
if (!file || !file.href) {
    node.error('no file url in event', msg);
    return null;
}
msg.url = file.href;
msg.filename = decodeURIComponent(file.href.split('/').pop() || 'upload.pdf');
if (!msg.filename.toLowerCase().endsWith('.pdf')) { msg.filename += '.pdf'; }
// Forward the JWT Islandora attaches to the event so Drupal serves the file.
msg.headers = {};
const auth = (msg.stompHeaders && msg.stompHeaders.Authorization) || (event.authorization);
if (auth) { msg.headers.Authorization = auth; }
msg.event = event; // keep for the status message
return msg;

const boundary = '----nrragboundary' + Date.now();
const filename = msg.filename || 'upload.pdf';
const head = Buffer.from(
    `--${boundary}\r\nContent-Disposition: form-data; name="files"; filename="${filename}"\r\nContent-Type: application/pdf\r\n\r\n`);
const tail = Buffer.from(`\r\n--${boundary}--\r\n`);
msg.payload = Buffer.concat([head, msg.payload, tail]);
msg.headers = {
    'Content-Type': 'multipart/form-data; boundary=' + boundary,
    'X-API-Key': env.get('RAGSVC_KEY') || ''
};
msg.url = (env.get('RAGSVC_URL') || 'http://host.docker.internal:8000') + '/ingest';
return msg;

const r = msg.payload.results[0];
const status = {
    type: 'rag-indexed',
    file: r.file,
    chunks: r.chunks,
    object: msg.event && msg.event.object ? msg.event.object.id : null,
    timestamp: new Date().toISOString()
};
node.warn('rag-indexed: ' + JSON.stringify(status));

// Optional write-back: set DRUPAL_URL (+ DRUPAL_AUTH, base64 user:pass) on the
// container to PATCH field_rag_indexed on the node. Adjust bundle/field names
// to the site's content model.
const drupal = env.get('DRUPAL_URL');
const uuid = status.object ? String(status.object).replace('urn:uuid:', '') : null;
if (!drupal || !uuid) { return [msg, null]; }

const patch = {
    url: drupal + '/jsonapi/node/islandora_object/' + uuid,
    method: 'PATCH',
    headers: {
        'Content-Type': 'application/vnd.api+json',
        'Accept': 'application/vnd.api+json',
        'Authorization': 'Basic ' + (env.get('DRUPAL_AUTH') || '')
    },
    payload: JSON.stringify({
        data: {
            type: 'node--islandora_object',
            id: uuid,
            attributes: { field_rag_indexed: true }
        }
    }),
    event: msg.event
};
return [msg, patch];
